model.expr:
sum by (host) (
  count_over_time(
    {
      job=~"systemd-journal|syslog",
      transport=~"kernel|",
      service!="syslog"
    }
    |~ "(?i)(buffer I/O error|blk_update_request|critical medium error|uncorrectable|bad sector|SMART.*fail|pending sector|reallocated sector|nvme.*(critical|reset|timeout|abort)|EXT4-fs error|XFS.*error|BTRFS.*error|remounting filesystem read-only|mmc.*(error|timeout)|sdhci.*(error|timeout)|under-voltage|machine check|mce:|hardware error|EDAC|memory failure|PCIe Bus Error|thermal.*critical|watchdog.*lockup|kernel panic)"
    !~ "(?i)(PCIe Bus Error.*severity=Correctable|AER: Correctable error received)"
    [5m]
  )
)
